#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_H 50
#define MAX_W 50

typedef struct {
    int r, c;
} Point;

typedef struct {
    Point q[MAX_H * MAX_W * 10];
    int front, rear;
} Queue;

void enqueue(Queue *q, int r, int c) {
    q->q[q->rear].r = r;
    q->q[q->rear].c = c;
    q->rear++;
}

Point dequeue(Queue *q) {
    return q->q[q->front++];
}

int is_empty(Queue *q) {
    return q->front == q->rear;
}

int bfs(char maze[MAX_H][MAX_W+1], int H, int W, int sr, int sc, int gr, int gc) {
    // Directions: up, down, left, right
    int dr[] = {-1, 1, 0, 0};
    int dc[] = {0, 0, -1, 1};

    // visited[r][c][k] = minimum steps to reach (r,c) having visited k ice cells in current chunk
    // We'll use a large enough 3D array
    int visited[MAX_H][MAX_W][MAX_H*MAX_W];
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            for (int k = 0; k < H*W; k++)
                visited[i][j][k] = -1;

    // Identify ice chunks using flood fill
    int chunk_id[MAX_H][MAX_W];
    int chunk_size[MAX_H*MAX_W];
    int ice_count = 0;
    memset(chunk_id, -1, sizeof(chunk_id));
    memset(chunk_size, 0, sizeof(chunk_size));

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (maze[i][j] == 'I' && chunk_id[i][j] == -1) {
                // BFS to find all connected ice cells
                Queue q;
                q.front = q.rear = 0;
                enqueue(&q, i, j);
                chunk_id[i][j] = ice_count;
                chunk_size[ice_count] = 1;

                while (!is_empty(&q)) {
                    Point p = dequeue(&q);
                    for (int d = 0; d < 4; d++) {
                        int nr = p.r + dr[d];
                        int nc = p.c + dc[d];
                        if (nr >= 0 && nr < H && nc >= 0 && nc < W && 
                            maze[nr][nc] == 'I' && chunk_id[nr][nc] == -1) {
                            chunk_id[nr][nc] = ice_count;
                            chunk_size[ice_count]++;
                            enqueue(&q, nr, nc);
                        }
                    }
                }
                ice_count++;
            }
        }
    }

    // BFS with state (r, c, steps_in_chunk) where steps_in_chunk is count of visited ice cells in current chunk
    // Actually we need to track per chunk visited count, but since we only move between chunks when leaving ice,
    // we can track the count for the current chunk.
    // Better approach: state = (r, c, chunk_visited_count) where chunk_visited_count is number of ice cells visited in current chunk
    // When we leave ice to non-ice, reset count to 0.
    // When we enter ice from non-ice, start counting.
    // When we move between ice cells in same chunk, increment count.
    // If count > chunk_size/2, that move is invalid.

    // We'll use a queue for BFS
    Queue q;
    q.front = q.rear = 0;

    // Initial state: at start, no chunk visited
    enqueue(&q, sr);
    enqueue(&q, sc);
    enqueue(&q, 0); // chunk_visited_count
    visited[sr][sc][0] = 0;

    while (!is_empty(&q)) {
        int r = dequeue(&q).r;
        int c = dequeue(&q).c;
        int cnt = dequeue(&q).r; // reuse Point struct, but cnt is stored in .r field
        // Actually we need to fix: we stored cnt as third enqueue, but dequeue returns Point.
        // Let's restructure: store state as three separate queues or use struct.
        // Quick fix: use a single queue with struct that holds r,c,cnt.
    }

    // Reimplement properly with a struct queue
    typedef struct {
        int r, c, cnt;
    } State;

    State queue[MAX_H * MAX_W * MAX_H * MAX_W];
    int front = 0, rear = 0;

    queue[rear++] = (State){sr, sc, 0};
    visited[sr][sc][0] = 0;

    while (front < rear) {
        State s = queue[front++];
        int r = s.r, c = s.c, cnt = s.cnt;

        if (r == gr && c == gc) {
            return visited[r][c][cnt];
        }

        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];

            if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
            if (maze[nr][nc] == '#') continue;

            if (maze[nr][nc] == 'I') {
                int cid = chunk_id[nr][nc];
                int new_cnt;
                if (maze[r][c] == 'I' && chunk_id[r][c] == cid) {
                    // Same chunk
                    new_cnt = cnt + 1;
                } else {
                    // Entering new chunk
                    new_cnt = 1;
                }
                if (new_cnt > chunk_size[cid] / 2) continue; // Would break the ice
                if (visited[nr][nc][new_cnt] == -1 || visited[nr][nc][new_cnt] > visited[r][c][cnt] + 1) {
                    visited[nr][nc][new_cnt] = visited[r][c][cnt] + 1;
                    queue[rear++] = (State){nr, nc, new_cnt};
                }
            } else {
                // Plain or goal
                int new_cnt = 0;
                if (visited[nr][nc][0] == -1 || visited[nr][nc][0] > visited[r][c][cnt] + 1) {
                    visited[nr][nc][0] = visited[r][c][cnt] + 1;
                    queue[rear++] = (State){nr, nc, 0};
                }
            }
        }
    }

    return -1;
}

int main() {
    int H, W;
    while (1) {
        scanf("%d %d", &H, &W);
        if (H == 0 && W == 0) break;

        char maze[MAX_H][MAX_W+1];
