                }
            }
        }

        /* Build graph:
           node 0..compCnt-1 : ice components
           node compCnt : S
           node compCnt+1 : G
           edges between adjacent traversable "regions"
        */
        int N = compCnt + 2;
        int Snode = compCnt;
        int Gnode = compCnt + 1;

