        int ecnt = 0;

        #define ADD_EDGE(u,v) do { \
            edges[ecnt].to = (v); \
            edges[ecnt].next = head[(u)]; \
            head[(u)] = ecnt++; \
        } while(0)

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (g[i][j] == '#') continue;

                int u;
                if (g[i][j] == 'X') u = comp[i][j];
                else if (g[i][j] == 'S') u = Snode;
